assertEquals(202, post(client, root.resolve("/api/v1/sessions/" + sessionId + "/prompt"),
        "{\"commandId\":\"command-1\",\"text\":\"hi\"}").statusCode());
JsonNode snapshot;
Instant deadline = Instant.now().plus(Duration.ofSeconds(5));
do {
    snapshot = json(client.send(HttpRequest.newBuilder(root.resolve("/api/v1/sessions/" + sessionId + "/snapshot")).GET().build(), HttpResponse.BodyHandlers.ofString()));
    if (snapshot.path("transcript").size() >= 2) break;
    if (Instant.now().isAfter(deadline)) {
        throw new AssertionError("snapshot did not reach terminal transcript: " + snapshot);
    }
    Thread.sleep(10);
} while (true);
assertEquals("hi", snapshot.path("transcript").get(0).path("text").asText());
assertEquals("hello", snapshot.path("transcript").get(1).path("text").asText());
assertTrue(snapshot.path("lastEventSeq").asLong() > 0);
